//! An icon glyph for the m3 widget library.
//!
//! Every glyph name resolves to a vendored Lucide SVG through the shared
//! SVG bank (`ux/shared/svg_icons.zig`, generated by
//! `scripts/gen_lucide_icons.py`), which rasterises and caches one surface
//! per (icon, px). The Material Symbols font is no longer used anywhere in
//! the Zig shell: a name with no mapping measures zero and paints nothing.
//!
//! `size` is the icon box in device pixels — a 24dp icon stays 24 pixels
//! regardless of the display's DPI scale.

const std = @import("std");
const cairo = @import("../../wl/buffer/shm.zig").cairo;
const svg_icons = @import("../../ux/shared/svg_icons.zig");

/// Icon glyph.
pub const Glyph = struct {
    glyph: []const u8 = "",
    size: f32 = 24.0,
    r: f32 = 0.94,
    g: f32 = 0.94,
    b: f32 = 0.96,
    a: f32 = 1.0,
    x: f32 = 0.0,
    y: f32 = 0.0,
    w: f32 = 0.0,
    h: f32 = 0.0,

    pub fn setGlyph(self: *Glyph, name: []const u8) void {
        self.glyph = name;
    }

    pub fn setSize(self: *Glyph, sp: f32) void {
        self.size = sp;
    }

    /// `a` defaults to fully opaque.
    pub fn setColor(self: *Glyph, red: f32, green: f32, blue: f32, alpha: f32) void {
        self.r = red;
        self.g = green;
        self.b = blue;
        self.a = alpha;
    }

    pub fn setGeometry(self: *Glyph, gx: f32, gy: f32, gw: f32, gh: f32) void {
        self.x = gx;
        self.y = gy;
        self.w = gw;
        self.h = gh;
    }

    pub fn glyphName(self: *const Glyph) []const u8 {
        return self.glyph;
    }

    pub fn glyphSize(self: *const Glyph) f32 {
        return self.size;
    }

    /// Measure icon pixel extent: a square box of `size` when the Lucide
    /// bank carries the name, zeroes otherwise (nothing would paint).
    pub fn measureExtents(self: *const Glyph, out_w: *f32, out_h: *f32) void {
        if (self.glyph.len == 0 or svg_icons.lucideName(self.glyph) == null) {
            out_w.* = 0;
            out_h.* = 0;
            return;
        }
        out_w.* = self.size;
        out_h.* = self.size;
    }

    /// Paint centred in the geometry box (the flex layout positions cells
    /// through `setGeometry`; unset geometry degrades to a `size` box at
    /// (x, y)).
    pub fn paint(self: *const Glyph, c: ?*cairo.cairo_t) void {
        if (self.glyph.len == 0) return;
        const cr = c orelse return;
        const half = @as(f64, self.size) * 0.5;
        const cx = if (self.w > 0.0) @as(f64, self.x) + @as(f64, self.w) * 0.5 else @as(f64, self.x) + half;
        const cy = if (self.h > 0.0) @as(f64, self.y) + @as(f64, self.h) * 0.5 else @as(f64, self.y) + half;
        _ = svg_icons.draw(cr, self.glyph, cx, cy, self.size, self.r, self.g, self.b, self.a, false);
    }

    /// Paint with the icon box's top-left at (px, py).
    pub fn paintAt(self: *const Glyph, c: ?*cairo.cairo_t, px: f32, py: f32) void {
        if (self.glyph.len == 0) return;
        const cr = c orelse return;
        const half = @as(f64, self.size) * 0.5;
        _ = svg_icons.draw(
            cr,
            self.glyph,
            @as(f64, px) + half,
            @as(f64, py) + half,
            self.size,
            self.r,
            self.g,
            self.b,
            self.a,
            false,
        );
    }
};

test "m3-glyph: measures and paints an icon name" {
    const t = std.testing;
    const surf = cairo.cairo_image_surface_create(cairo.CAIRO_FORMAT_ARGB32, 64, 64);
    defer cairo.cairo_surface_destroy(surf);
    const cr = cairo.cairo_create(surf);
    defer cairo.cairo_destroy(cr);

    var gl = Glyph{};
    gl.setGlyph("close");
    gl.setSize(24.0);
    gl.setGeometry(0, 0, 32, 32);

    var w: f32 = 0;
    var h: f32 = 0;
    gl.measureExtents(&w, &h);
    // A mapped name measures its square icon box; zero would mean the name
    // fell out of the Lucide bank.
    try t.expectEqual(@as(f32, 24.0), w);
    try t.expectEqual(@as(f32, 24.0), h);

    gl.paint(cr);
    try t.expect(cairo.cairo_status(cr) == cairo.CAIRO_STATUS_SUCCESS);
    gl.paintAt(cr, 8, 8);
    try t.expect(cairo.cairo_status(cr) == cairo.CAIRO_STATUS_SUCCESS);
}

test "m3-glyph: empty glyph and size scaling" {
    const t = std.testing;
    var empty = Glyph{};
    var w: f32 = 1;
    var h: f32 = 1;
    empty.measureExtents(&w, &h);
    try t.expectEqual(@as(f32, 0.0), w);
    try t.expectEqual(@as(f32, 0.0), h);
    // Null-safe: an empty glyph must not need a context at all.
    empty.paint(null);
    empty.paintAt(null, 0, 0);

    // An unmapped name measures nothing and paints nothing.
    var unmapped = Glyph{};
    unmapped.setGlyph("definitely-not-a-glyph");
    unmapped.measureExtents(&w, &h);
    try t.expectEqual(@as(f32, 0.0), w);
    try t.expectEqual(@as(f32, 0.0), h);
    unmapped.paint(null);
    unmapped.paintAt(null, 0, 0);

    var gl = Glyph{};
    gl.setGlyph("widgets");
    var w1: f32 = 0;
    var h1: f32 = 0;
    var w2: f32 = 0;
    var h2: f32 = 0;
    gl.setSize(16.0);
    gl.measureExtents(&w1, &h1);
    gl.setSize(32.0);
    gl.measureExtents(&w2, &h2);
    // Doubling the absolute size must grow the measured box, not shrink it.
    try t.expect(w2 > w1 and h2 > h1);
}

test "m3-glyph: getters round-trip" {
    const t = std.testing;
    var gl = Glyph{};
    gl.setGlyph("search");
    gl.setSize(18.0);
    gl.setColor(1, 1, 1, 0.8);
    try t.expectEqualStrings("search", gl.glyphName());
    try t.expectEqual(@as(f32, 18.0), gl.glyphSize());
    try t.expectEqual(@as(f32, 0.8), gl.a);
}
